async ({ workspace: { read, search, glob } }) => {
  const [rs, fns, still, npmExit, attempts] = await Promise.all([
    read("src/renderers/result-summary.ts", { format: "raw" }),
    glob([".pi/functions/**/*"]),
    search("still pending", { limit: 20 }),
    search("exit ${", { limit: 20 }),
    search("attempts", { path: ".pi/functions", limit: 60 }),
  ]);
  return { rs: rs.content, fns: fns.entries, still, npmExit, attempts: attempts.matches.map(m => `${m.file}:${m.line} ${m.text}`) };
}
